    "r90.a77f2d2326e3": "<span class=\"abadge\">{{svg1}}Nunca pagarás cuota</span><span class=\"abadge\">{{svg2}}Una de las 300 plazas</span><span class=\"abadge\">Revisión humana prevista</span>",
